CREATE TRIGGER organization_outbox_ins AFTER INSERT ON organization
WHEN NOT EXISTS (SELECT 1 FROM local_pref WHERE "key" = 'sync.applying')
BEGIN INSERT OR REPLACE INTO sync_outbox (table_name, row_id, op_id) VALUES ('organization', NEW.id, lower(hex(randomblob(16)))); END;

